// C implementation of vstodo cmdReset header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_reset.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_reset.go.\n\n#ifndef VSTODO_C_CMD_RESET_H\n#define VSTODO_C_CMD_RESET_H\n\n// Reset HEAD to a specified commit.\n// Equivalent to Go cmdReset function.\n// app — vstodo application context pointer\n// args — reset mode and commit reference (e.g. \"--hard <commit>\", \"<commit>\")\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_reset(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_RESET_H